extends Resource
class_name EnemyStats

@export var name: String = ""
@export var max_health: int = 10
@export var speed: float = 100.0
@export var damage: int = 10
@export var color: Color = Color.WHITE

extends CharacterBody2D

@export var stats: EnemyStats

var current_health: int = 0

func _ready() -> void:
	if stats:
		current_health = stats.max_health
		$ColorRect.color = stats.color

func take_damage(amount: int) -> void:
	current_health -= amount
	if current_health <= 0:
		queue_free()

extends Node2D

@export var enemy_scene: PackedScene = preload("res://scenes/Enemy.tscn")
@export var enemy_types: Array[EnemyStats] = []

func _ready() -> void:
	spawn_enemies()

func spawn_enemies() -> void:
	for i in enemy_types.size():
		var stats = enemy_types[i]
		if stats and enemy_scene:
			var enemy = enemy_scene.instantiate()
			enemy.stats = stats
			add_child(enemy)
			enemy.position = Vector2(i * 64, 0)

func take_damage_all(amount: int) -> void:
	for child in get_children():
		# The scene root script is Enemy (extends CharacterBody2D)
		if child.has_method("take_damage"):
			child.take_damage(amount)

extends SceneTree

func _init() -> void:
	# Verify resources load as EnemyStats
	var res_paths = [
		"res://resources/enemies/goblin.tres",
		"res://resources/enemies/orc.tres",
		"res://resources/enemies/dragon.tres"
	]
	for p in res_paths:
		var res = load(p)
		if not res:
			push_error("Failed to load: " + p)
			continue
		if not res is EnemyStats:
			push_error(p + " is not EnemyStats: " + str(res))
			continue
		print(p, " -> ", res.name, ", max_health=", res.max_health, ", color=", res.color)

	# Verify Enemy scene loads
	var enemy_scene = load("res://scenes/Enemy.tscn")
	if not enemy_scene:
		push_error("Failed to load Enemy.tscn")
	else:
		print("Enemy.tscn loaded OK")

	# Verify Spawner scene loads and instances correctly
	var spawner_scene = load("res://scenes/Spawner.tscn")
	if not spawner_scene:
		push_error("Failed to load Spawner.tscn")
	else:
		var spawner = spawner_scene.instantiate()
		# Assign the exported array programmatically
		var types = []
		for p in res_paths:
			types.append(load(p))
		spawner.enemy_types = types
		root.add_child(spawner)
		print("Spawner instantiated, types count=", spawner.enemy_types.size())

		# Trigger _ready
		# In SceneTree script _init, we need to add to root to trigger _ready
		await spawner.ready
		print("Spawner ready. Children count=", spawner.get_child_count())

		# Damage all
		spawner.take_damage_all(30)

		await spawner.get_tree().process_frame
		print("After take_damage_all(30) + idle frame, children count=", spawner.get_child_count())

		print("Done")
		quit()

